import * as THREE from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  group.userData.cleanup = () => {
    gsap.killTweensOf([group, photoMaterial, captionGroup, hairline, scrim]);
    group.traverse((child) => {
      if (child.geometry) child.geometry.dispose();
      if (child.material) {
        if (Array.isArray(child.material)) {
          child.material.forEach(m => m.dispose());
        } else {
          child.material.dispose();
        }
      }
    });
  };
  group.userData.handlers = {};

  const imageTexture = ctx.textureLoader.load(config.imageUrl);
  const depthTexture = ctx.textureLoader.load(config.depthMapUrl);

  // === PHOTO PLANE WITH DISPLACEMENT-MAPPED GEOMETRY ===
  const planeGeo = new THREE.PlaneGeometry(4.0, 2.5, 64, 64);

  // Apply vertex displacement from depth map
  const posAttr = planeGeo.getAttribute('position');
  const positions = posAttr.array;
  const normals = planeGeo.getAttribute('normal').array;
  const depthImage = depthTexture.image;

  const canvas = new OffscreenCanvas(depthImage.width || 256, depthImage.height || 256);
  const canvasCtx = canvas.getContext('2d');
  if (depthImage instanceof HTMLImageElement || depthImage instanceof HTMLCanvasElement) {
    canvasCtx.drawImage(depthImage, 0, 0);
  }
  const imgData = canvasCtx.getImageData(0, 0, canvas.width, canvas.height);
  const data = imgData.data;

  const displacementAmp = 0.18;
  for (let i = 0; i < positions.length; i += 3) {
    const uvX = ((positions[i] / 4.0) + 0.5);
    const uvY = 1 - ((positions[i + 1] / 2.5) + 0.5);
    const px = Math.floor(uvX * (canvas.width - 1));
    const py = Math.floor(uvY * (canvas.height - 1));
    const idx = (py * canvas.width + px) * 4;
    const depth = (data[idx] + data[idx + 1] + data[idx + 2]) / 765; // Normalize 0-1

    positions[i + 2] += (depth * 2 - 1) * displacementAmp;
  }
  posAttr.needsUpdate = true;
  planeGeo.computeVertexNormals();

  const photoMaterial = new THREE.MeshStandardMaterial({
    map: imageTexture,
    metalness: 0,
    roughness: 1.0,
    transparent: true,
    opacity: 0,
  });

  const photoPlane = new THREE.Mesh(planeGeo, photoMaterial);
  photoPlane.position.z = 0;
  group.add(photoPlane);

  // === SCRIM GRADIENT ===
  const scrimGeo = new THREE.PlaneGeometry(4.0, 1.5);

  const gradW = 256, gradH = 256;
  const gradData = new Uint8Array(gradW * gradH * 4);

  for (let y = 0; y < gradH; y++) {
    const t = y / gradH;
    const alpha = Math.floor(t * 235);

    for (let x = 0; x < gradW; x++) {
      const i = (y * gradW + x) * 4;
      gradData[i] = 11;
      gradData[i + 1] = 11;
      gradData[i + 2] = 16;
      gradData[i + 3] = alpha;
    }
  }

  const gradTex = new THREE.DataTexture(gradData, gradW, gradH, THREE.RGBAFormat);
  gradTex.needsUpdate = true;

  const scrimMat = new THREE.MeshBasicMaterial({
    map: gradTex,
    transparent: true,
    depthWrite: false,
  });

  const scrim = new THREE.Mesh(scrimGeo, scrimMat);
  scrim.position.set(0, -1.0, 0.02);
  group.add(scrim);

  // === CAPTION BLOCK ===
  const captionGroup = new THREE.Group();
  captionGroup.position.set(-1.8, -0.75, 0.1);

  let yPos = 0;
  const rhythm = 0.25;

  // Kicker
  const kickerMesh = ctx.fontAtlas.createTextMesh(
    config.textContent?.kicker || "NOVA ATELIER / GENEVA",
    { fontSize: 0.09, letterSpacing: 0.12, lineHeight: 1.2 }
  );
  if (kickerMesh) {
    kickerMesh.position.y = yPos;
    captionGroup.add(kickerMesh);
    yPos -= rhythm;
  }

  // Headline
  const headlineMesh = ctx.fontAtlas.createTextMesh(
    config.textContent?.headline || "Time, Machined.",
    { fontSize: 0.34, letterSpacing: -0.01, lineHeight: 1.1 }
  );
  if (headlineMesh) {
    headlineMesh.position.y = yPos;
    captionGroup.add(headlineMesh);
    yPos -= rhythm * 1.5;
  }

  // Accent hairline
  const hairlineGeo = new THREE.PlaneGeometry(0.75, 0.02);
  const hairlineMat = new THREE.MeshStandardMaterial({
    color: 0xff2a38,
    emissive: 0xff2a38,
    emissiveIntensity: 1.8,
  });
  const hairline = new THREE.Mesh(hairlineGeo, hairlineMat);
  hairline.position.y = yPos;
  hairline.position.z = 0.01;
  captionGroup.add(hairline);
  yPos -= rhythm;

  // Body
  const bodyMesh = ctx.fontAtlas.createTextMesh(
    config.textContent?.body || "Every case begins as a single billet of 904L steel.",
    { fontSize: 0.13, letterSpacing: 0, lineHeight: 1.5 }
  );
  if (bodyMesh) {
    bodyMesh.position.y = yPos;
    captionGroup.add(bodyMesh);
    yPos -= rhythm * 2;
  }

  // Caption
  const captionMesh = ctx.fontAtlas.createTextMesh(
    config.textContent?.caption || "CALIBRE NA-01 / 72 HOUR RESERVE",
    { fontSize: 0.09, letterSpacing: 0.12, lineHeight: 1.4 }
  );
  if (captionMesh) {
    captionMesh.position.y = yPos;
    captionGroup.add(captionMesh);
  }

  captionGroup.position.y += 0.4;
  group.add(captionGroup);

  // === ANIMATIONS ===
  gsap.to(photoMaterial, {
    opacity: 1,
    duration: 0.5,
    ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
  });

  gsap.to(captionGroup.position, {
    y: -0.75,
    duration: 0.7,
    ease: 'cubic-bezier(0.215,0.61,0.355,1)',
    delay: 0.12,
  });

  // === CINEMATIC PRIMITIVES ===
  if (ctx.primitives?.['parallax-scroll']) {
    ctx.primitives['parallax-scroll'](group, {
      intensity: 0.35,
      trigger: 'scroll',
    });
  }

  return group;
}
